#include <stdexcept>
inline uint64_t hex64(const std::string& s){return std::stoull(s,nullptr,16);}
inline ip6_t read_ip(){std::string a,b;std::cin>>a>>b;return {hex64(a),hex64(b)};}
inline void image_write_json(const ImageData& d){
    auto loc=[](ImageLoc x){std::cout<<'['<<x.stage<<','<<x.cell<<']';};
    auto fronts=[&](const std::vector<ImageFront>& v,int width){
        std::cout<<'[';bool first=true;
        for(auto e:v){if(!first)std::cout<<',';first=false;std::ostringstream key;key<<std::hex<<std::setfill('0')<<std::setw(width)<<e.key;
            std::cout<<"[\""<<key.str()<<"\","<<e.loc.stage<<','<<e.loc.cell<<']';}
        std::cout<<']';};
    std::cout<<"{\"root\":";if(d.root.stage<0)std::cout<<"null";else loc(d.root);
    std::cout<<",\"front16\":";fronts(d.front16,4);std::cout<<",\"front64\":";fronts(d.front64,16);
    std::cout<<",\"cells\":[";for(int s=0;s<RAM_NUM;++s){if(s)std::cout<<',';std::cout<<d.cells[s];}
    std::cout<<"],\"banks\":[";for(int s=0;s<RAM_NUM;++s){if(s)std::cout<<',';std::cout<<'[';bool first=true;
        for(const auto& word:d.banks[s]){if(!first)std::cout<<',';first=false;std::cout<<'"'<<image_word_hex(word)<<'"';}std::cout<<']';}
    std::cout<<"],\"bitmaps\":[";for(size_t i=0;i<d.bitmaps.size();++i){if(i)std::cout<<',';std::ostringstream mask;mask<<std::hex<<std::setfill('0')<<std::setw(16)<<d.bitmaps[i];std::cout<<'"'<<mask.str()<<'"';}
    std::cout<<"],\"nexthops\":[";for(size_t i=0;i<d.nexthops.size();++i){if(i)std::cout<<',';std::cout<<d.nexthops[i];}std::cout<<"]}";
}
inline ImageData image_read_wire(){
    ImageData d;std::cin>>d.root.stage>>d.root.cell;
    for(auto* v:{&d.front16,&d.front64}){size_t n;std::cin>>n;v->resize(n);for(auto& e:*v){std::string key;std::cin>>key>>e.loc.stage>>e.loc.cell;e.key=hex64(key);}}
    for(auto& n:d.cells)std::cin>>n;
    for(auto& bank:d.banks){size_t n;std::cin>>n;bank.resize(n);for(auto& word:bank){std::string text;std::cin>>text;word=image_word_from_hex(text);}}
    size_t n;std::cin>>n;d.bitmaps.resize(n);for(auto& mask:d.bitmaps){std::string text;std::cin>>text;mask=hex64(text);}
    std::cin>>n;d.nexthops.resize(n);for(auto& hop:d.nexthops)std::cin>>hop;
    if(!std::cin)throw std::runtime_error("wire input");return d;
}
