def run_managed_child(path, data):
    if os.uname().machine != "x86_64" or not hasattr(os, "waitid"):
        raise ValueError("public checker requires Linux x86_64 process supervision")
    prctl(36, 1)  # PR_SET_CHILD_SUBREAPER
