        return bytes(output[0])
    finally:
        # Repeated SIGINT/SIGTERM cannot interrupt descendant cleanup. A
        # pending signal is delivered after cleanup and prevents success.
        with blocked_interruptions():
            try:
                if process is not None:
                    cleanup_group(process)
            finally:
                sel.close()
                for stream in streams:
                    stream.close()


