/// Normalized prefix key: the address with the host bits cleared plus its length.
struct FibKey {
    uint64_t hi;
    uint64_t lo;
    uint8_t len;
    bool operator==(const FibKey& other) const {
        return hi == other.hi && lo == other.lo && len == other.len;
    }
};

struct FibKeyHash {
    size_t operator()(const FibKey& key) const {
        uint64_t h = key.hi * 0x9E3779B97F4A7C15ULL;
        h ^= key.lo + 0x165667B19E3779F9ULL + (h << 6) + (h >> 2);
        h ^= static_cast<uint64_t>(key.len) * 0xC2B2AE3D27D4EB4FULL;
        h ^= h >> 29;
        h *= 0xBF58476D1CE4E5B9ULL;
        h ^= h >> 32;
        return static_cast<size_t>(h);
    }
};

/// Prefix table with last-write-wins updates and longest prefix match lookup.
class PrefixTable {
public:
    void put(uint64_t hi, uint64_t lo, uint8_t len, uint32_t hop);
    bool lookup(const ip6_t& ip, uint32_t& hop) const;
    void clear();
    size_t size() const { return entries_.size(); }
    const std::unordered_map<FibKey, uint32_t, FibKeyHash>& entries() const { return entries_; }
private:
    std::unordered_map<FibKey, uint32_t, FibKeyHash> entries_;
    uint64_t length_mask_ = 0;   // bit l set when a prefix of length l exists
};
