#include "image_build.hpp"

#include <algorithm>
#include <map>
#include <vector>

namespace {

constexpr uint32_t HOP_NULL = 4194303u;   // the reserved "no hop" encoding
constexpr uint32_t ABSENT_CHILD = 15u << 6;

inline uint64_t mask_bits(uint64_t value, int len) {
    if (len <= 0) return 0;
    if (len >= 64) return ~0ULL;
    return (~0ULL << (64 - len));
}

struct Pref {
    uint64_t hi;
    uint64_t lo;
    uint8_t len;
    uint32_t hop;
};

struct BNode {
    int type = 0;
    int origin = 0;
    int G = 0;                 // global depth
    uint64_t reg_hi = 0;       // region address (first G bits)
    uint64_t reg_lo = 0;
    int parent = -1;
    bool is_bulk = false;      // placed inside a bulk block
    std::vector<int> children;
    std::vector<uint8_t> child_keys;
    std::vector<int> local;    // locally owned prefixes
    std::vector<int> inlined;  // inline prefixes (TYPE4 / TYPE5)
    int stage = 0;
    uint32_t cell = 0;
    int height = 0;
    uint32_t bmp = HOP_NULL;
    uint32_t bitmap_id = 0;
    uint32_t ni_base = 0;
    int bulk_stage = 0;
    uint32_t bulk_base = 0;
    uint64_t bulk_bitmap = 0;
};

class Builder {
public:
    ImageData build(const PrefixTable& table);
private:
    int addNode(int type, int origin, int G, uint64_t reg_hi, uint64_t reg_lo, int parent);
    int buildTree(const std::vector<int>& idxs, int origin, int G,
                  uint64_t reg_hi, uint64_t reg_lo, int parent,
                  int bmp_len, uint32_t bmp_hop);
    int subtreeHeight(int idx) const;
    void assignStages(int idx, int forced);
    uint8_t chunkOf(const Pref& p, int G) const;
    uint64_t inlineFragment(const Pref& p, int origin) const;

    std::vector<Pref> prefs_;
    std::vector<BNode> nodes_;
    const PrefixTable* table_ = nullptr;
};

inline uint64_t Builder::chunkOf(const Pref& p, int G) const {
    if (G + 6 <= 64) return (p.hi >> (64 - G - 6)) & 0x3FULL;
    if (G >= 64) return (p.lo >> (64 - (G - 64) - 6)) & 0x3FULL;
    int hi_bits = 64 - G;  // bits taken from the high word
    uint64_t value = (p.hi & mask_bits(p.hi, hi_bits)) << (6 - hi_bits);
    value |= (p.lo >> (64 - (6 - hi_bits))) & mask_bits(p.lo, 6 - hi_bits);
    return value & 0x3FULL;
}

inline uint64_t Builder::inlineFragment(const Pref& p, int origin) const {
    int rel = static_cast<int>(p.len) - origin;
    if (rel <= 0) return 0;
    if (rel > 64) rel = 64;
    if (origin == 64) return (p.lo & mask_bits(p.lo, rel)) << (64 - rel);
    uint64_t bits = (p.hi >> origin) & mask_bits(p.hi, rel);
    return bits << (64 - rel);
}

int Builder::addNode(int type, int origin, int G, uint64_t reg_hi, uint64_t reg_lo, int parent) {
    BNode node;
    node.type = type;
    node.origin = origin;
    node.G = G;
    node.reg_hi = reg_hi;
    node.reg_lo = reg_lo;
    node.parent = parent;
    nodes_.push_back(node);
    return static_cast<int>(nodes_.size()) - 1;
}

int Builder::buildTree(const std::vector<int>& idxs, int origin, int G,
                       uint64_t reg_hi, uint64_t reg_lo, int parent,
                       int bmp_len, uint32_t bmp_hop) {
    // The node bitmap is the hop of the longest global prefix of length <= the
    // node depth that matches the whole region of this node.
    int my_bmp_len = bmp_len;
    uint32_t my_bmp_hop = bmp_hop;
    for (int l = G; l > my_bmp_len; --l) {
        uint64_t mhi, mlo;
        if (l <= 64) {
            mhi = mask_bits(reg_hi, l);
            mlo = 0;
        } else {
            mhi = reg_hi;
            mlo = mask_bits(reg_lo, l - 64);
        }
        auto it = table_->entries().find(FibKey{mhi, mlo, static_cast<uint8_t>(l)});
        if (it != table_->entries().end()) {
            my_bmp_len = l;
            my_bmp_hop = it->second;
            break;
        }
    }

    int count = static_cast<int>(idxs.size());
    int type;
    if (count == 1) type = 4;
    else if (count == 2) type = 5;
    else type = 0;  // decided from the child count

    int me = addNode(type, origin, G, reg_hi, reg_lo, parent);
    nodes_[me].bmp = my_bmp_hop;

    if (type == 4 || type == 5) {
        nodes_[me].inlined = idxs;
        return me;
    }

    std::vector<int> outer;
    for (int idx : idxs) {
        int rel = static_cast<int>(prefs_[idx].len) - G;
        if (rel <= 5) nodes_[me].local.push_back(idx);
        else outer.push_back(idx);
    }

    std::map<uint8_t, std::vector<int>> groups;
    for (int idx : outer) groups[static_cast<uint8_t>(chunkOf(prefs_[idx], G))].push_back(idx);

    int child_count = static_cast<int>(groups.size());
    nodes_[me].type = child_count <= 2 ? 1 : (child_count <= 6 ? 2 : 3);

    for (auto& kv : groups) {
        uint64_t chi = reg_hi;
        uint64_t clo = reg_lo;
        uint8_t key = kv.first;
        // insert the six key bits at position G
        if (G + 6 <= 64) {
            chi |= static_cast<uint64_t>(key & 0x3F) << (64 - G - 6);
        } else {
            int hi_bits = 64 - G;
            chi |= static_cast<uint64_t>((key >> (6 - hi_bits)) & mask_bits(key, hi_bits));
            uint64_t low = static_cast<uint64_t>(key) & mask_bits(key, 6 - hi_bits);
            clo |= low << (64 - (6 - hi_bits));
        }
        int child = buildTree(kv.second, origin, G + 6, chi, clo, me, my_bmp_len, my_bmp_hop);
        nodes_[child].child_keys.size();
        nodes_[me].children.push_back(child);
        nodes_[me].child_keys.push_back(key);
    }
    return me;
}

int Builder::subtreeHeight(int idx) const {
    int h = 0;
    for (int c : nodes_[idx].children) h = std::max(h, 1 + subtreeHeight(c));
    return h;
}

void Builder::assignStages(int idx, int forced) {
    int h = subtreeHeight(idx);
    nodes_[idx].height = h;
    nodes_[idx].stage = (forced >= 0) ? forced : h;
    bool bulk_parent = nodes_[idx].type == 3;
    for (int c : nodes_[idx].children) {
        // Every child of a TYPE3 node is a bulk child; they share one stage.
        int child_stage = bulk_parent ? (h - 1) : -1;
        if (bulk_parent) nodes_[c].is_bulk = true;
        assignStages(c, child_stage);
    }
}

ImageData Builder::build(const PrefixTable& table) {
    table_ = &table;
    nodes_.clear();
    prefs_.clear();

    ImageData image;

    // Collect the live prefixes.
    for (const auto& kv : table.entries()) {
        Pref p;
        p.hi = kv.first.hi;
        p.lo = kv.first.lo;
        p.len = kv.first.len;
        p.hop = kv.second;
        prefs_.push_back(p);
    }

    // Split into the three owner forests.
    std::vector<int> f0, f16, f64;
    for (int i = 0; i < static_cast<int>(prefs_.size()); ++i) {
        int len = prefs_[i].len;
        if (len <= 16) f0.push_back(i);
        else if (len <= 64) f16.push_back(i);
        else f64.push_back(i);
    }

    int root_index = -1;
    if (!f0.empty()) {
        root_index = buildTree(f0, 0, 0, 0, 0, -1, -1, HOP_NULL);
        assignStages(root_index, -1);
    }

    // The depth 16 roots, keyed by the high 16 address bits.
    std::map<uint64_t, std::vector<int>> groups16;
    for (int i : f16) groups16[prefs_[i].hi >> 48].push_back(i);
    for (auto& kv : groups16) {
        uint64_t reg_hi = kv.first << 48;
        int idx = buildTree(kv.second, 16, 16, reg_hi, 0, -1, -1, HOP_NULL);
        assignStages(idx, -1);
        ImageFront front;
        front.key = kv.first;
        front.loc.stage = nodes_[idx].stage;
        image.front16.push_back(front);
    }

    // The depth 64 roots, keyed by the high 64 address bits.
    std::map<uint64_t, std::vector<int>> groups64;
    for (int i : f64) groups64[prefs_[i].hi].push_back(i);
    for (auto& kv : groups64) {
        uint64_t reg_hi = kv.first;
        int idx = buildTree(kv.second, 64, 64, reg_hi, 0, -1, -1, HOP_NULL);
        assignStages(idx, -1);
        ImageFront front;
        front.key = kv.first;
        front.loc.stage = nodes_[idx].stage;
        image.front64.push_back(front);
    }

    // Place the nodes inside their stages.
    std::vector<std::vector<int>> by_stage(RAM_NUM);
    for (size_t i = 0; i < nodes_.size(); ++i) by_stage[nodes_[i].stage].push_back(static_cast<int>(i));

    for (int s = 0; s < RAM_NUM; ++s) {
        uint32_t offset = 0;
        // Bulk blocks first: they occupy contiguous two cell slots.
        for (int idx : by_stage[s]) {
            if (nodes_[idx].type != 3) continue;
            if (nodes_[idx].bulk_stage != s) continue;
            for (int c : nodes_[idx].children) {
                nodes_[c].cell = offset;
