            uint32_t v = static_cast<uint32_t>(field(row, rec + 63 + 32 * k, 32));
            if (v == ABSENT_CHILD) {
                seen_absent = true;
                continue;
            }
            if (seen_absent) return false;  // present children come first
            int key = static_cast<int>(v & 0x3F);
            int cstage = static_cast<int>((v >> 6) & 0xF);
            if (cstage > 10) return false;
            if (key <= last_key) return false;
            last_key = key;
            child_field[k] = v;
        }
    } else if (type == 3) {
        if (field(row, rec + 249, 7) != 0) return false;
        bulk_bitmap = field(row, rec + 63, 64);
        bulk_base = static_cast<uint32_t>(field(row, rec + 127, 22));
        bulk_stage = static_cast<int>(field(row, rec + 149, 4));
        if (bulk_stage > 10) return false;
        if ((bulk_base & 1) != 0) return false;
        bool seen_absent = false;
        int last_key = -1;
        for (int k = 0; k < 3; ++k) {
            uint32_t v = static_cast<uint32_t>(field(row, rec + 153 + 32 * k, 32));
            if (v == ABSENT_CHILD) {
                seen_absent = true;
                continue;
            }
            if (seen_absent) return false;
            int key = static_cast<int>(v & 0x3F);
            int cstage = static_cast<int>((v >> 6) & 0xF);
            if (cstage > 10) return false;
            if (key <= last_key) return false;
            last_key = key;
            child_field[k] = v;
            if ((bulk_bitmap >> key) & 1ULL) return false;  // direct and bulk keys are disjoint
