std::string image_word_hex(const std::bitset<256>& bits) {
    std::string out(64, '0');
    for (int i = 0; i < 64; ++i) {
        unsigned v = 0;
        for (int b = 0; b < 4; ++b) v |= bits[4 * i + b] ? 1u << b : 0;
        out[63 - i] = "0123456789abcdef"[v];
    }
    return out;
}

std::bitset<256> image_word_from_hex(const std::string& text) {
    if (text.size() != 64) throw std::runtime_error("word length");
    std::bitset<256> out;
    for (int i = 0; i < 64; ++i) {
        char c = text[63 - i];
        unsigned v = c <= '9' ? c - '0' : c - 'a' + 10;
        if (v > 15) throw std::runtime_error("word hex");
        for (int b = 0; b < 4; ++b) out[4 * i + b] = (v >> b) & 1;
    }
    return out;
}

bool MemoryImage::load(const ImageData& proposed) {
    Validator validator;
    if (!validator.validate(proposed)) return false;
    data_ = proposed;
    table_.clear();
    for (const auto& entry : validator.fib) table_.put(entry.hi, entry.lo, entry.len, entry.hop);
    loaded_ = true;
    return true;
}

nexthop_t MemoryImage::lookup(ip6_t ip) const {
    if (!loaded_) return LPM_INVALID_NH;
    uint32_t hop = 0;
    if (!table_.lookup(ip, hop)) return LPM_INVALID_NH;
    return hop;
}
